function sumarMeses(f,n){const d=new Date(f+"T12:00:00");const dia=d.getDate();d.setMonth(d.getMonth()+n);if(d.getDate()<dia)d.setDate(0);return d.toISOString().slice(0,10);}
function sumarDias(f,n){const d=new Date(f+"T12:00:00");d.setDate(d.getDate()+n);return d.toISOString().slice(0,10);}
