const PROVINCIA_TERRITORIO={
"01":"ALA","02":"CLM","03":"VAL","04":"AND","05":"CYL","06":"EXT","07":"BAL","08":"CAT","09":"CYL","10":"EXT","11":"AND","12":"VAL",
"13":"CLM","14":"AND","15":"GAL","16":"CLM","17":"CAT","18":"AND","19":"CLM","20":"GIP","21":"AND","22":"ARA","23":"AND","24":"CYL",
"25":"CAT","26":"RIO","27":"GAL","28":"MAD","29":"AND","30":"MUR","31":"NAV","32":"GAL","33":"AST","34":"CYL","35":"CAN","36":"GAL",
"37":"CYL","38":"CAN","39":"CANT","40":"CYL","41":"AND","42":"CYL","43":"CAT","44":"ARA","45":"CLM","46":"VAL","47":"CYL","48":"BIZ",
"49":"CYL","50":"ARA","51":"CEU","52":"MEL",
};
const territorioDeIne=(ine)=>PROVINCIA_TERRITORIO[String(ine||"").padStart(5,"0").slice(0,2)]||null;
const NO_DA2=["NAV","ALA","BIZ","GIP","CEU","MEL","EST"];
const NORMA_DA2="disposición adicional 2.ª.Uno Ley 29/1987 (STJUE 3-9-2014, C-127/12; redacción de la Ley 26/2014 y de la Ley 11/2021)";
function normativaNoResidentes(o={}){
const fmt=(v)=>Math.round(v).toLocaleString("es-ES")+" €";
const herederos=o.herederos||[];
if(o.causanteResidente){
const nr=herederos.filter((h)=>h.residente===false);
if(!nr.length)return null;
return{regla:"b",ccaa:o.ccaaCausante,estado:V,norma:NORMA_DA2+", letra b",
motivo:`${nr.map((h)=>h.nombre).join(", ")} no ${nr.length>1?"residen":"reside"} en España: ${nr.length>1?"aplican":"aplica"} la normativa de la comunidad de residencia del causante (DA 2.ª.Uno.1.b Ley 29/1987) y ${nr.length>1?"presentan":"presenta"} el modelo 650 ante la Agencia Tributaria (DA 2.ª.Dos), con representante en España.`};
}
const porTerr={},sinUbicar=[];
for(const b of o.bienes||[]){
const v=Math.max(0,Number(b.valor)||0);if(!v)continue;
const t=b.ccaa||territorioDeIne(b.ine);
if(!t){sinUbicar.push(b.descripcion||b.tipo||"bien");continue;}
porTerr[t]=r2((porTerr[t]||0)+v);
}
const orden=Object.entries(porTerr).sort((a,b)=>b[1]-a[1]);
const avisoSin=sinUbicar.length?` No consta dónde están ${sinUbicar.length===1?"este bien":"estos bienes"}: ${sinUbicar.join(", ")}. Indica la comunidad en la ficha del bien (las cuentas, en la de la oficina) si puede cambiar el resultado.`:"";
if(!orden.length){
const porHeredero=Object.fromEntries(herederos.map((h)=>[h.id,h.ccaaResidencia&&!NO_DA2.includes(h.ccaaResidencia)?h.ccaaResidencia:"EST"]));
return{regla:"a-sin-bienes",ccaa:"EST",porHeredero,estado:sinUbicar.length?P:V,norma:NORMA_DA2+", letra a, segundo inciso",reparto:{},sinUbicar,
motivo:`No hay bienes situados en España con ubicación conocida: cada heredero aplica la normativa de la comunidad en la que resida (DA 2.ª.Uno.1.a); los que no residen en España, la ley estatal.${avisoSin}`};
}
const[t1,v1]=orden[0];
const empate=orden.length>1&&Math.abs(orden[1][1]-v1)<0.01;
const nom=(t)=>(REGLAS[t]?REGLAS[t].nombre:t);
const detalle=orden.map(([t,v])=>`${nom(t)} ${fmt(v)}`).join(", ");
if(NO_DA2.includes(t1))return{regla:"a",ccaa:"EST",propuesta:t1,estado:P,norma:NORMA_DA2+", letra a; Concierto Económico (Ley 12/2002) o Convenio con Navarra (Ley 28/1990): punto de conexión de no residentes PENDIENTE",reparto:porTerr,sinUbicar,
motivo:`El mayor valor de los bienes en España está en ${nom(t1)} (${detalle}), territorio fuera de la disposición adicional 2.ª (régimen foral o ciudad autónoma). Se calcula con la ley estatal, el resultado más alto, hasta confirmar si corresponde la normativa foral.${avisoSin}`};
return{regla:"a",ccaa:t1,estado:empate||sinUbicar.length?P:V,norma:NORMA_DA2+", letra a",reparto:porTerr,sinUbicar,
motivo:`Causante no residente: se aplica la normativa de ${nom(t1)}, donde está el mayor valor de los bienes situados en España (${detalle}) (DA 2.ª.Uno.1.a Ley 29/1987). Se presenta ante la Agencia Tributaria (modelo 650).${empate?" Hay empate de valores entre dos comunidades: elige tú cuál aplicar.":""}${avisoSin}`};
}
function aplicarColacion(derechos,herederos,o={}){
const porId=Object.fromEntries((herederos||[]).map((h)=>[h.id,h]));
const peso=(id)=>(derechos[id]||[]).filter((d)=>d.tipo==="pleno"||d.tipo==="nuda").reduce((s,d)=>s+d.fraccion,0);
const forzoso=(h)=>h&&!h.renuncia&&["desc","asc"].includes(linea(h));
const conDon=(herederos||[]).filter((h)=>(Number(h.donacionColacionable)||0)>0);
if(!conDon.length)return null;
const notas=[],avisos=[];
const foral=o.vecindad&&o.vecindad!=="comun";
if(foral&&!o.colacionOrdenada){
avisos.push(`Donaciones a traer a la partición: con vecindad civil ${VECINDADES[o.vecindad]||o.vecindad} la colación tiene reglas propias (en Cataluña solo si el causante la ordenó, art. 464-17 CCCat; resto de derechos forales PENDIENTE de cotejo). No se ha aplicado. Si el causante la ordenó, márcalo en el expediente.`);
return{derechos,notas,avisos,aplicada:false,filas:[]};
}
for(const h of conDon){
if(h.renuncia)avisos.push(`${h.nombre} renuncia: no colaciona (art. 1036 CC), aunque la donación puede reducirse si es inoficiosa (arts. 817-820 CC).`);
else if(h.dispensaColacion)notas.push(`${h.nombre}: donación dispensada de colación por el causante (art. 1036 CC). Se imputa a la legítima y, en lo que exceda, al tercio libre (arts. 819 y 825 CC).`);
else if(!forzoso(h))avisos.push(`${h.nombre} no es heredero forzoso: lo donado no se colaciona (art. 1035 CC); cuenta solo para calcular las legítimas (art. 818 CC).`);
}
let grupo=(herederos||[]).filter((h)=>forzoso(h)&&peso(h.id)>0);
const D=(h)=>(h.dispensaColacion?0:Math.max(0,Number(h.donacionColacionable)||0));
if(grupo.length<2||!grupo.some((h)=>D(h)>0)){
if(grupo.some((h)=>D(h)>0))notas.push("Colación: solo hay un heredero forzoso en la partición; no hay con quién colacionar (art. 1035 CC).");
return{derechos,notas,avisos,aplicada:false,filas:[]};
}
const N=Math.max(0,Number(o.neto)||0);
const w0=Object.fromEntries(grupo.map((h)=>[h.id,peso(h.id)]));
const W=grupo.reduce((s,h)=>s+w0[h.id],0);
const relictoGrupo=W*N;
const fuera=[];
let r={};
for(let i=0;i<20;i++){
const act=grupo.filter((h)=>!fuera.includes(h.id));
const Wa=act.reduce((s,h)=>s+w0[h.id],0);
const masa=relictoGrupo+act.reduce((s,h)=>s+D(h),0);
r={};
let nuevoFuera=false;
for(const h of act){r[h.id]=masa*w0[h.id]/Wa-D(h);if(r[h.id]<-0.005){fuera.push(h.id);nuevoFuera=true;}}
if(!nuevoFuera)break;
}
for(const id of fuera)r[id]=0;
const nuevo={};
for(const[id,lista]of Object.entries(derechos))nuevo[id]=lista.map((d)=>({...d}));
const filas=[];
for(const h of grupo){
const f=N>0?Math.max(0,r[h.id])/N:0,k=w0[h.id]>0?f/w0[h.id]:0;
nuevo[h.id]=(nuevo[h.id]||[]).map((d)=>(d.tipo==="pleno"||d.tipo==="nuda"?{...d,fraccion:d.fraccion*k}:d)).filter((d)=>d.fraccion>1e-12);
filas.push({id:h.id,nombre:h.nombre,donacion:r2(D(h)),cuotaSinColacion:r2(w0[h.id]*N),recibeDelCaudal:r2(Math.max(0,r[h.id])),excedido:fuera.includes(h.id)});
}
const masaTotal=r2(relictoGrupo+grupo.reduce((s,h)=>s+D(h),0));
notas.push(`Colación (arts. 1035-1050 CC): a lo que reciben los herederos forzosos del caudal (${Math.round(relictoGrupo).toLocaleString("es-ES")} €) se suman las donaciones colacionables, por su valor a la fecha de la partición (art. 1045), hasta una masa de ${Math.round(masaTotal).toLocaleString("es-ES")} €; cada uno toma de menos lo que ya recibió (art. 1047). `+
filas.filter((x)=>x.donacion>0).map((x)=>`${x.nombre}: donación ${Math.round(x.donacion).toLocaleString("es-ES")} €, recibe del caudal ${Math.round(x.recibeDelCaudal).toLocaleString("es-ES")} € en lugar de ${Math.round(x.cuotaSinColacion).toLocaleString("es-ES")} €`).join("; ")+".");
for(const x of filas.filter((q)=>q.excedido))avisos.push(`${x.nombre} recibió en vida más de lo que le corresponde en la partición: no recibe nada del caudal y no devuelve el exceso, salvo que la donación sea inoficiosa y deba reducirse (arts. 817-820 y 1047 CC). Revisar las legítimas.`);
avisos.push("Colación aplicada con el valor de las donaciones a la fecha de la partición que consta en el expediente (art. 1045 CC). Comprueba que no hay gastos excluidos (alimentos, educación, regalos de costumbre: arts. 1041-1044 CC) ni dispensa en la escritura de donación.");
return{derechos:nuevo,notas,avisos,aplicada:true,filas,masa:masaTotal,norma:"arts. 1035-1050 CC",estado:V};
}
function acumulacionPrevias(h,fechaFallecimiento){
const lista=Array.isArray(h.adquisicionesPrevias)?h.adquisicionesPrevias:[];
const lim=sumarMeses(fechaFallecimiento,-48);
const dentro=[],fueraPlazo=[];
for(const a of lista){
const bl=Math.max(0,Number(a.baseLiquidable)||0);
if(!bl||!a.fecha)continue;
(a.fecha>=lim&&a.fecha<=fechaFallecimiento?dentro:fueraPlazo).push({...a,baseLiquidable:bl});
}
const suma=r2(dentro.reduce((s,a)=>s+a.baseLiquidable,0)+Math.max(0,Number(h.donacionesPreviasBL)||0));
return{suma,dentro,fueraPlazo,limite:lim,norma:"art. 30.2 y 30.3 Ley 29/1987",estado:V};
}
