const add=(paso,valor,norma,estado)=>{traza.push({paso,valor:plR2(valor),norma,estado});if(estado===PL_P&&norma)pend.push(norma);};
base=plR2(plPos(base));
add("Base imponible: valor de lo donado",base,"art. 9.1.b Ley 29/1987 (inmuebles: al menos el valor de referencia, art. 9.3)",PL_V);
const rd=D.reduccion?D.reduccion(g,h):null;
