const q=cuotaCon(bl,soloV);
let cuota=q.k.cuota;const bon=[];
for(const b of D.bonif?D.bonif(g,{fecha,bl,cuota}):[]){if(soloV&&b.estado!==PL_V)continue;const imp=plR2(cuota*b.pct);bon.push({...b,importe:imp});cuota=plR2(cuota-imp);}
