const plTerrNombre=(id)=>(TERRITORIOS.find((t)=>t[0]===id)||[id,id])[1];
const plValorFiscal=(b)=>(plEsInm(b)?Math.max(b.valor,b.valorReferencia||0):b.valor);
const plDuenos=(b,hayC)=>(b.titularidad==="ganancial"&&hayC?{T:0.5,C:0.5}:b.titularidad==="conyuge"&&hayC?{T:0,C:1}:{T:1,C:0});
function plSacar(p,acto){
const bienes=p.bienes.map((b)=>({...b}));
if(!acto||!acto.bienId)return{bienes,sale:null};
const b=bienes.find((q)=>q.id===acto.bienId);
if(!b)return{bienes,sale:null};
const dinero=!plEsInm(b)&&acto.importe>0;
const imp=dinero?Math.min(b.valor,plPos(acto.importe)):b.valor;
const frac=b.valor>0?imp/b.valor:0;
const du=plDuenos(b,!!p.conyuge);
const sale={bien:{...b},importe:plR2(imp),frac,valorFiscal:plR2(plValorFiscal(b)*frac),duenos:du,dinero,inmueble:plEsInm(b)};
if(frac>=0.9999)bienes.splice(bienes.indexOf(b),1);else{b.valor=plR2(b.valor-imp);if(b.valorReferencia)b.valorReferencia=plR2(b.valorReferencia*(1-frac));}
return{bienes,sale};
}
const PL_FORMAS={
intestada:{titulo:"Sin testamento",sub:"Reparto que fija la ley"},
usufructo:{titulo:"«Uno para el otro» con usufructo universal",sub:"Usufructo de todo al cónyuge, nuda propiedad a los hijos, cautela socini"},
legado:{titulo:"Legado del usufructo de la vivienda",sub:"Usufructo de la vivienda al cónyuge (o su cuota legal si es mayor), el resto a los hijos en pleno dominio"},
tercio:{titulo:"Tercio libre en pleno dominio al cónyuge",sub:"Tercio libre en pleno dominio y la cuota legal en usufructo; los hijos, el resto"},
};
const plFormas=()=>PL_FORMAS;
function plDerechosForma(forma,P,bienesT){
const C=P.conyuge,n=P.hijos.length;
if(!C||!n||forma==="intestada"||forma==="usufructo")return null;
const der={C:[]};for(const h of P.hijos)der[h.id]=[];
if(forma==="legado"){
const total=bienesT.reduce((s,b)=>s+plValorFiscal(b)*plDuenos(b,true).T,0)||1;
const viv=bienesT.filter((b)=>b.tipo==="vivienda").reduce((s,b)=>s+plValorFiscal(b)*plDuenos(b,true).T,0);
const f=Math.min(1,Math.max(viv/total,1/3));
der.C.push({tipo:"usufructo",fraccion:f});
for(const h of P.hijos){der[h.id].push({tipo:"nuda",fraccion:f/n,usufructuarioId:"C"});if(f<1)der[h.id].push({tipo:"pleno",fraccion:(1-f)/n});}
return{derechos:der,f,notaDerechos:`Legado al cónyuge del usufructo de la vivienda (${Math.round(f*100)} % del caudal, con un mínimo de su cuota legal de un tercio en usufructo); los hijos, herederos por partes iguales.`};
}
if(forma==="tercio"){
der.C.push({tipo:"pleno",fraccion:1/3},{tipo:"usufructo",fraccion:1/3});
for(const h of P.hijos)der[h.id].push({tipo:"pleno",fraccion:1/3/n},{tipo:"nuda",fraccion:1/3/n,usufructuarioId:"C"});
return{derechos:der,notaDerechos:"Tercio de libre disposición en pleno dominio al cónyuge, más su cuota legal en usufructo sobre el tercio de mejora; los hijos, herederos por partes iguales."};
}
return null;
}
