for(const h of P.hijos)L.push({id:h.id,nombre:h.nombre,relacion:"hijo",edad:h.edad+anios,discapacidad:h.discapacidad,patrimonioPreexistente:h.patrimonio+((extra.ppH||{})[h.id]||0),adquisicionesPrevias:(extra.previas||{})[h.id]});
