function planEscenarios(p0){
const P=plNormalizar(p0);
const out=[],avisos=[];
if(!P.hijos.length&&!P.conyuge)return{plan:P,escenarios:[],avisos:["Añade al cónyuge o a los hijos: el comparador necesita a quién heredaría."]};
if(!P.bienes.length)return{plan:P,escenarios:[],avisos:["Añade el patrimonio (vivienda, otros inmuebles, cuentas, valores)."]};
const base=PL_FORMAS[P.supuestos.testamentoBase]?P.supuestos.testamentoBase:"intestada";
const formas=P.conyuge&&P.hijos.length?["intestada","usufructo","legado","tercio"]:["intestada"];
for(const f of formas)out.push(plEscenario(P,"t-"+f,{forma:f,titulo:PL_FORMAS[f].titulo,sub:P.conyuge&&P.hijos.length?PL_FORMAS[f].sub:P.hijos.length?"Los hijos por partes iguales (igual con testamento a partes iguales)":"Hereda el cónyuge",tipo:"testamento"}));
const baseTit=PL_FORMAS[base].titulo.replace(/«|»/g,"");
const D=P.donacion||{};
if(D.bienId)out.push(plEscenario(P,"donacion",{forma:base,titulo:"Donación en vida",sub:`${plDescActo(P,D)} · el resto, ${baseTit.toLowerCase()}`,acto:{tipo:"donacion",...D}}));
else out.push({id:"donacion",titulo:"Donación en vida",aplicable:false,motivo:"Elige qué se dona y a quién para calcularla."});
const vp=plVecindadPacto(P.titular.vecindad),PT=PL_PACTOS[vp]||PL_PACTOS.comun;
const Pa=P.pacto||{};
if(!PT.permite)out.push({id:"pacto",titulo:"Pacto sucesorio",aplicable:false,motivo:PT.nota,norma:PT.norma,estado:PT.estado});
else if(Pa.bienId)out.push(Object.assign(plEscenario(P,"pacto",{forma:base,titulo:"Pacto sucesorio",sub:`${(PT.figuras.find(([k])=>k===Pa.figura)||PT.figuras[0])[1]} · ${plDescActo(P,Pa)}`,acto:{tipo:"pacto",...Pa},fiscalPacto:PT.fiscal,irpfPendiente:!!PT.irpfPendiente}),{pactoTerritorio:{...PT,vecindad:vp}}));
else out.push({id:"pacto",titulo:"Pacto sucesorio",aplicable:false,motivo:`Con vecindad ${VECINDADES[vp]||vp} cabe: ${PT.figuras.map((f)=>f[1]).join("; ")}. Elige qué se transmite y a quién.`,norma:PT.figuras.map((f)=>f[2]).join("; "),estado:PT.estado});
const Sg=P.seguro||{};
if(plPos(Sg.capital)>0)out.push(plEscenario(P,"seguro",{forma:base,titulo:"Seguro de vida con beneficiario",sub:`${plEur(plPos(Sg.capital))} para ${Sg.a==="C"?P.conyuge?P.conyuge.nombre||"el cónyuge":"—":(P.hijos.find((h)=>h.id===Sg.a)||{}).nombre||"—"} · ${baseTit.toLowerCase()}`,seguro:Sg}));
else out.push({id:"seguro",titulo:"Seguro de vida con beneficiario",aplicable:false,motivo:"Indica el capital y el beneficiario."});
const Rs=P.residencia||{};
if(Rs.destino&&REGLAS[Rs.destino]&&Rs.destino!==P.titular.ccaa)out.push(plEscenario(P,"residencia",{forma:base,titulo:`Cambio de residencia a ${plTerrNombre(Rs.destino)}`,sub:`Traslado el ${plFecha(Rs.fecha||P.fecha)} · ${baseTit.toLowerCase()}`,residencia:{destino:Rs.destino,fecha:Rs.fecha||P.fecha}}));
else out.push({id:"residencia",titulo:"Cambio de residencia",aplicable:false,motivo:"Elige la comunidad de destino y la fecha prevista del traslado."});
const ok=out.filter((e)=>e.aplicable);
const ref=ok.find((e)=>e.id==="t-intestada");
for(const e of ok)e.ahorro=ref?plR2(ref.prudente-e.prudente):0;
const mejor=ok.slice().sort((a,b)=>a.prudente-b.prudente)[0]||null;
if(P.supuestos.horizonte<4)avisos.push(`Con un horizonte de ${P.supuestos.horizonte} años, las donaciones y pactos de hoy se acumulan a la herencia (art. 30 Ley 29/1987): ya está incluido en el cálculo.`);
return{plan:P,escenarios:out,mejor:mejor?mejor.id:null,avisos,supuestos:plSupuestos(P)};
}
function plDescActo(P,A){
const b=(P.bienes||[]).find((q)=>q.id===A.bienId);
const quien=A.a==="todos"||!A.a?(P.hijos.length>1?"a los hijos por partes iguales":`a ${(P.hijos[0]||{}).nombre||"el hijo"}`):`a ${(P.hijos.find((h)=>h.id===A.a)||{}).nombre||"—"}`;
if(!b)return"—";
return`${plEsInm(b)?b.descripcion||"Inmueble":plEur(Math.min(b.valor,plPos(A.importe)||b.valor))+" de "+(b.descripcion||"una cuenta")} ${quien}`;
}
function plSupuestos(P){
return[
`Valores de hoy (${plFecha(P.fecha)}); no se proyecta revalorización ni inflación.`,
`Fallece primero ${P.titular.nombre||"el titular"}, dentro de ${P.supuestos.horizonte} años${P.conyuge?`, y ${P.conyuge.nombre||"el cónyuge"} ${P.supuestos.intervalo} años después`:""}; las edades avanzan con el tiempo (el usufructo se valora con la edad de entonces).`,
P.conyuge?"En la segunda herencia los hijos heredan por partes iguales y el cónyuge no ha hecho donaciones.":"",
"Reglas fiscales vigentes hoy: un cambio legal posterior cambia el resultado.",
"Se suponen cumplidos los requisitos formales de cada beneficio (escritura pública, origen de los fondos, plazos) y que los hijos residen en la misma comunidad.",
"Ajuar doméstico del 3 % de los inmuebles de uso residencial incluido en cada herencia (art. 15 Ley 29/1987, criterio del motor); deudas y gastos de notaría y Registro, no.",
].filter(Boolean);
}
