const HEREDA_PARTES={"archivos":{"municipios":"partes/municipios.js?v=202610200546","biblioteca":"partes/biblioteca.js?v=202610200546","normas":"partes/normas.js?v=202610200546","mapas":"partes/mapas.js?v=202610200546","carpeta":"partes/carpeta.js?v=202610200546","familia":"partes/familia.js?v=202610200546","calculadora":"partes/calculadora.js?v=202610200546"},"nucleo":["nucleo/motor.js?v=202610200546","nucleo/app.js?v=202610200546"]};
